#include "ringbuf.h"
#include <stdio.h>
#include <string.h>
#include <assert.h>

#define ASSERT_EQ(a, b) do { if ((a) != (b)) { fprintf(stderr, "FAIL: %s == %zu (expected %zu)\n", #a, (a), (b)); return 1; } } while(0)
#define ASSERT_STR_EQ(a, b) do { if (memcmp((a),(b),sizeof(a)) != 0 || ((char*)(a))[sizeof(a)-1] != '\0' || ((char*)(b))[sizeof(b)-1] != '\0') { fprintf(stderr, "FAIL: strings differ\n"); return 1; } } while(0)

int main(void) {
    /* Test NULL safety */
    assert(rb_size(NULL) == 0);
    assert(rb_capacity(NULL) == 0);
    rb_destroy(NULL);
    rb_clear(NULL);
    assert(rb_read(NULL, NULL, 0) == 0);
    assert(rb_write(NULL, NULL, 0) == 0);
    assert(rb_peek(NULL, NULL, 0) == 0);

    /* Test create/destroy with invalid capacity */
    assert(rb_create(0) == NULL);
    assert(rb_destroy(rb_create(5)) == (void)0);

    {
        ringbuf_t *rb = rb_create(5);
        ASSERT_EQ(rb_capacity(rb), 5);
        ASSERT_EQ(rb_size(rb), 0);

        /* Write some bytes */
        uint8_t w[] = {1, 2, 3, 4, 5};
        size_t n = rb_write(rb, w, 5);
        ASSERT_EQ(n, 5);
        ASSERT_EQ(rb_size(rb), 5);

        /* Buffer full - write should return 0 */
        n = rb_write(rb, w, 1);
        ASSERT_EQ(n, 0);
        ASSERT_EQ(rb_size(rb), 5);

        /* Read a few bytes */
        uint8_t r[3] = {0};
        n = rb_read(rb, r, 3);
        ASSERT_EQ(n, 3);
        ASSERT_EQ(rb_size(rb), 2);
        assert(r[0] == 1 && r[1] == 2 && r[2] == 3);

        /* Peek should see same bytes */
        uint8_t p[3] = {0};
        n = rb_peek(rb, p, 3);
        ASSERT_EQ(n, 2);
        assert(p[0] == 4 && p[1] == 5);

        /* Read the remaining */
        uint8_t r2[5] = {0};
        n = rb_read(rb, r2, 5);
        ASSERT_EQ(n, 2);
        assert(r2[0] == 4 && r2[1] == 5);

        /* Buffer empty */
        ASSERT_EQ(rb_size(rb), 0);
        n = rb_read(rb, r, 1);
        ASSERT_EQ(n, 0);

        /* Test wrap-around: write fills past capacity boundary on read too */
        uint8_t w2[] = {10, 20};
        n = rb_write(rb, w2, 2);
        ASSERT_EQ(n, 2);
        ASSERT_EQ(rb_size(rb), 2);

        /* Clear and verify */
        rb_clear(rb);
        ASSERT_EQ(rb_size(rb), 0);

        uint8_t w3[] = {100, 101, 102};
        n = rb_write(rb, w3, 6);  /* more than capacity */
        ASSERT_EQ(n, 3);           /* should write what fits and stop at capacity */
        ASSERT_EQ(rb_size(rb), 3);

        uint8_t r3[3] = {0};
        n = rb_read(rb, r3, 3);
        ASSERT_EQ(n, 3);
        assert(r3[0] == 100 && r3[1] == 101 && r3[2] == 102);

        rb_destroy(rb);
    }

    /* Test wrap-around properly */
    {
        ringbuf_t *rb = rb_create(4);
        uint8_t w[] = {1, 2};
        rb_write(rb, w, 2);
        uint8_t r[2] = {0};
        rb_read(rb, r, 2);  /* drain it */

        /* Now write more bytes — head will wrap past the position where we wrote before */
        uint8_t w2[] = {10, 11, 12, 13};
        size_t n = rb_write(rb, w2, 4);
        ASSERT_EQ(n, 4);
        ASSERT_EQ(rb_size(rb), 4);

        uint8_t r2[4] = {0};
        n = rb_read(rb, r2, 4);
        ASSERT_EQ(n, 4);
        assert(r2[0] == 10 && r2[1] == 11 && r2[2] == 12 && r2[3] == 13);

        rb_destroy(rb);
    }

    printf("All tests passed!\n");
    return 0;
}

